if (v.visualStair) {
  // Identity hit region stays unchanged; photo artwork may extend into the hall.
  el("polygon", { points: pts(v.polygon), "class": "geo-enclosure" }, gg);
  var art = el("g", { "class": "geo-stair-art", "data-stair-art": v.id, "aria-hidden": "true", "pointer-events": "none" }, L.feat);
  el("polygon", { points: pts(v.visualStair.landing), "class": "geo-landing" }, art);
  v.visualStair.flights.forEach(function (flight) {
    el("polygon", { points: pts(flight), "class": "geo-flight" }, art);
    var fb = bbox(flight);
    for (var sx = fb.x + 3; sx < fb.x + fb.w; sx += 3) el("line", { x1: sx, y1: fb.y, x2: sx, y2: fb.y + fb.h, "class": "treads" }, art);
  });
} else drawStairBox(gg, v.polygon, "v");
